import{z as n,x as s,o as t,c as p,q as r,j as A,D as e,d as i,s as B,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"JIT 的深化","description":"","frontmatter":{"title":"JIT 的深化","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cg-jit-deep.md","filePath":"cs/cg-jit-deep.md","lastUpdated":1791063341000}'),C={name:"cs/cg-jit-deep.md"};function d(T,a,c,f,h,m){const l=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="jit-的深化" tabindex="-1">JIT 的深化 <a class="header-anchor" href="#jit-的深化" aria-label="Permalink to &quot;JIT 的深化&quot;">​</a></h1><div class="epigraph"><p>JIT 的全部赌注是：过去的行为能替未来担保；守卫是担保书，去优化是违约条款。</p><footer>—— 据 Hölzle, Chambers and Ungar, PLDI, 1992；Gal et al., PLDI, 2009 整理</footer></div><p><a href="/cs/cg-linker-deep">上一课</a>把优化搬到装配时；JIT 更进一步，把编译搬进运行时。<a href="/cs/method-jit">方法 JIT</a>给过计数热点、整方法编译、换入口；<a href="/cs/tracing-jit">追踪 JIT</a>给过热路径加守卫；<a href="/cs/inline-caching">内联缓存</a>给过调用点的缓存。缺的是把它们装成一台完整机器的四个部件：分层策略、去优化、代码缓存、与 GC 的握手。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单层 JIT 有一个两难：编译得快，代码就糙；编译得好，启动就卡。分层是工程答案：底层（解释器或基线编译器）跑得快、代码糙，顺手收集 profile——类型见过哪些、分支往哪边走、哪个调用点热；顶层消费 profile 做投机优化：假设类型不变、分支不变、这个对象不逃逸（<a href="/cs/jit-escape-analysis">逃逸分析在 JIT 里</a>的用法），生成只在假设成立时正确的代码。假设错了怎么办，是投机方案的生死题：代码不能在错误假设上继续跑，也不能一错就全盘重来——必须有结构化的违约处理，这就是去优化。</p><p><span class="marginnote">术语翻译：守卫就是编译器埋在优化代码里的一条 if 检查——「这个对象的类型还是我假设的那个吗？」；去优化（deopt）则是检查失败时的整套善后：把机器码栈帧原样翻译回解释器栈帧，再从失败点继续跑。守卫是担保书，去优化是违约条款的执行流程。</span></p><h3 id="去优化的机器" tabindex="-1">去优化的机器 <a class="header-anchor" href="#去优化的机器" aria-label="Permalink to &quot;去优化的机器&quot;">​</a></h3><p>去优化（uncommon trap）在编译时给每条守卫记录一份状态映射：优化帧里的每个值如何还原成解释器帧需要的形态。守卫失效时，按映射把栈就地重建成未优化的等价帧，执行从失效点继续。这笔元数据是 JIT 的核心资产：有了它，优化代码不再需要保守——猜错的代价从「崩溃或慢十倍」变成「回解释器重新数热度」。</p><p><span class="marginnote">再优化不能立刻重跑：失效一次马上重编译，同一份 profile 会让它再失效一次，编译器开始空转。工程惯例是失效后让计数重新积累、或给 profile 加上「见过反例」的标记，再谈重编译。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分层策略是参数化的问题：计数阈值多少、每层收哪些 profile、后台编译线程几个、队列满了丢谁。HotSpot 把 C1 按监控量分成几档再交给 C2；V8 走 Ignition → Sparkplug → Maglev → TurboFan。层数与层间策略是各家调了几十年的东西——每加一层都是一份编译器代码加一个策略测试面，层数不是免费的。代码缓存是另一个预算：大小上限、回收策略、碎片整理；补丁要原子——内联缓存从单形改多形、守卫改跳转，都不能让别的线程看见半张跳转表。</p><p><span class="marginnote">数字实例：计数阈值是千到万这个量级——例如某函数被调用约一万次才触发优化编译（HotSpot 各档阈值即此量级）。若守卫失效后立即重编译，同一份 profile 会让它再失效一次：一秒内编译数万字节指令却全白费，这就是要靠「重新积累热度」防住的编译风暴。</span></p>',12)),(t(),A(o,null,{default:e(()=>[B(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20RUN%5B%22%E8%A7%A3%E9%87%8A%20%2F%20%E5%9F%BA%E7%BA%BF%E5%B1%82%E8%BF%90%E8%A1%8C%22%5D%20--%3E%20PROF%5B%22%E8%AE%A1%E6%95%B0%E4%B8%8E%20profile%22%5D%0A%20%20PROF%20--%3E%20HOT%7B%22%E8%BF%87%E9%98%88%E5%80%BC%EF%BC%9F%22%7D%0A%20%20HOT%20--%3E%7C%E5%90%A6%7C%20RUN%0A%20%20HOT%20--%3E%7C%E6%98%AF%7C%20OPT%5B%22%E4%BC%98%E5%8C%96%E7%BC%96%E8%AF%91%EF%BC%9A%E6%8A%95%E6%9C%BA%20%2B%20%E5%AE%88%E5%8D%AB%22%5D%0A%20%20OPT%20--%3E%20EXEC%5B%22%E8%BF%90%E8%A1%8C%E4%BC%98%E5%8C%96%E4%BB%A3%E7%A0%81%22%5D%0A%20%20EXEC%20--%3E%20GUARD%7B%22%E5%AE%88%E5%8D%AB%E6%88%90%E7%AB%8B%EF%BC%9F%22%7D%0A%20%20GUARD%20--%3E%7C%E6%98%AF%7C%20EXEC%0A%20%20GUARD%20--%3E%7C%E5%90%A6%7C%20DEOPT%5B%22%E5%8E%BB%E4%BC%98%E5%8C%96%EF%BC%9A%E9%87%8D%E5%BB%BA%E8%A7%A3%E9%87%8A%E5%B8%A7%22%5D%0A%20%20DEOPT%20--%3E%20RUN%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"与 GC 的握手是去优化元数据的第二份用途：优化帧里的对象引用要有精确的映射表，GC 才能在栈上准确扫描；safepoint 让运行中的优化代码在安全点停下。同一份「栈上有什么」的账，去优化用来重建帧，GC 用来扫描——两件事共用一份元数据，这也是为什么去优化数据与 safepoint 在运行时里总是成对出现。方法 JIT 与追踪 JIT 的取舍在这个框架下变得清楚：方法级的帧结构是静态的，状态映射简单；追踪级的退出点在循环中间，映射更碎、守卫更多，换来的是更少的编译开销。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：投机优化像抄近路，守卫是路口的告示牌——近路封了就按地图退回大路（去优化），而不是摔进沟里。同一张「地图」（状态映射）平时还被巡逻队（GC）拿来核对路上有哪些行人（栈上的对象引用），所以地图必须永远与路况同步。")],-1)),(t(),A(o,null,{default:e(()=>[B(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20META%5B%22%E7%BC%96%E8%AF%91%E6%9C%9F%E8%AE%B0%E5%BD%95%EF%BC%9A%E4%BC%98%E5%8C%96%E5%B8%A7%E7%9A%84%E7%8A%B6%E6%80%81%E6%98%A0%E5%B0%84%22%5D%20--%3E%7C%22%E7%94%A8%E9%80%94%E4%B8%80%EF%BC%9A%E5%AE%88%E5%8D%AB%E5%A4%B1%E6%95%88%22%7C%20DEOPT%5B%22%E6%8C%89%E6%98%A0%E5%B0%84%E9%87%8D%E5%BB%BA%E8%A7%A3%E9%87%8A%E5%B8%A7%22%5D%0A%20%20DEOPT%20--%3E%20CONT%5B%22%E4%BB%8E%E5%A4%B1%E6%95%88%E7%82%B9%E7%BB%A7%E7%BB%AD%E8%A7%A3%E9%87%8A%E6%89%A7%E8%A1%8C%22%5D%0A%20%20META%20--%3E%7C%22%E7%94%A8%E9%80%94%E4%BA%8C%EF%BC%9Asafepoint%20%E5%81%9C%E4%B8%8B%22%7C%20GC%5B%22GC%20%E6%8C%89%E5%90%8C%E4%B8%80%E6%98%A0%E5%B0%84%E6%89%AB%E6%A0%88%E4%B8%8A%E5%BC%95%E7%94%A8%22%5D%0A%20%20GC%20--%3E%20RESUME%5B%22%E5%9B%9E%E5%88%B0%E4%BC%98%E5%8C%96%E4%BB%A3%E7%A0%81%E7%BB%A7%E7%BB%AD%E8%B7%91%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>AOT 与 JIT 的边界不收在本课：提前编译换启动与可预测性，JIT 换峰值与自适应，混合形态（AOT 基线加 JIT 顶层，或 PGO 指导 AOT）是工程折中。本课不写具体引擎的调参，也不覆盖运行时 GC 的算法本身。JIT 的正确性合同在这里收口：守卫覆盖不到的假设不能写进优化代码；UB 语言里，JIT 要自己先定义「未定义」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分层解决单层两难：底层收 profile，顶层做投机。</li><li>去优化是投机的违约条款：守卫失效时按状态映射重建未优化帧。</li><li>再优化要防风暴：失效后重新积累热度，不让编译器空转。</li><li>代码缓存与补丁原子性是运行时的硬预算。</li><li>oop 映射一份两用：去优化重建帧，GC 精确扫描。</li><li>出处：Deutsch and Schiffman, 1984；Hölzle, Chambers and Ungar, 1992；Bala, Duesterwald and Banerjia, 2000；Gal et al., 2009。</li></ul>',4))])}const I=n(C,[["render",d]]);export{u as __pageData,I as default};
